changeSet.sql:
drop index if exists uk_integration_connection_enabled_sdv;
update integration_connections set purpose = 'DOCUMENT_STORE_DELIVERY' where purpose = 'SDV_DELIVERY';
update integration_connections set acknowledgement_mode = 'SUBMISSION_ACK'
 where acknowledgement_mode = 'SDV_SUBMISSION_ACK';
update integration_connections set last_failure_category = 'DOCUMENT_STORE_CONNECTION_TEST_FAILED'
 where last_failure_category = 'SDV_CONNECTION_TEST_FAILED';
update package_export_records set destination_type = 'document-store' where destination_type = 'sdv';
update delivery_submissions set destination_type = 'document-store' where destination_type = 'sdv';
create unique index uk_integration_connection_enabled_document_store
    on integration_connections (tenant_id)
 where purpose = 'DOCUMENT_STORE_DELIVERY' and enabled = true;

rollback.sql:
drop index if exists uk_integration_connection_enabled_document_store;
update integration_connections set purpose = 'SDV_DELIVERY' where purpose = 'DOCUMENT_STORE_DELIVERY';
update integration_connections set acknowledgement_mode = 'SDV_SUBMISSION_ACK'
 where acknowledgement_mode = 'SUBMISSION_ACK';
update integration_connections set last_failure_category = 'SDV_CONNECTION_TEST_FAILED'
 where last_failure_category = 'DOCUMENT_STORE_CONNECTION_TEST_FAILED';
update package_export_records set destination_type = 'sdv' where destination_type = 'document-store';
update delivery_submissions set destination_type = 'sdv' where destination_type = 'document-store';
create unique index uk_integration_connection_enabled_sdv
    on integration_connections (tenant_id)
 where purpose = 'SDV_DELIVERY' and enabled = true;
